```python
def get_unique_elements(mylist):
    # Create a dictionary to store the unique elements and their counts
    unique_elements = {}

    # Iterate through the input list and increment the count of each element in the dictionary
    for element in mylist:
        if element not in unique_elements:
            unique_elements[element] = 1
        else:
            unique_elements[element] += 1

    # Return the unique elements in the list
    return list(unique_elements.keys())
```

